<?php defined('BASEPATH') OR exit('No direct script access allowed');
$esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
$amount=function($v){return number_format((float)$v,2);};
$dateLabel=function($from,$to){
    $a=DateTime::createFromFormat('!Y-m-d',(string)$from); $b=DateTime::createFromFormat('!Y-m-d',(string)$to);
    if(!$a) return '';
    if(!$b || $a==$b) return $a->format('F j, Y');
    if($a->format('Y-m')===$b->format('Y-m')) return $a->format('F j').'–'.$b->format('j, Y');
    return $a->format('F j, Y').' – '.$b->format('F j, Y');
};
$timeLabel=function($time){$d=DateTime::createFromFormat('!H:i',(string)$time);return $d?$d->format('g:i A'):'';};
?>
